func measureFormAction(m *db.Measure) templ.SafeURL {
	if m == nil {
		return "/measures"
	}
	return templ.SafeURL("/measures/" + m.ID.String())
}

func measureFieldVal(m *db.Measure, field string) string {
	if m == nil {
		if field == "status" {
			return "planned"
		}
		return ""
	}
	switch field {
	case "name":
		return m.Name
	case "category":
		return m.Category
	case "owner":
		return m.Owner
	case "description":
		return m.Description
	case "status":
		return m.Status
	}
	return ""
}

